SST_PW=$(openssl rand -base64 24); APP_PW=$(openssl rand -base64 24)
mysql -u root -e "
CREATE USER 'sst'@'localhost' IDENTIFIED BY [REDACTED];
GRANT RELOAD, LOCK TABLES, PROCESS, REPLICATION CLIENT ON *.* TO 'sst'@'localhost';
CREATE DATABASE IF NOT EXISTS appdb;
CREATE USER 'appuser'@'%' IDENTIFIED BY [REDACTED];
GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
"
printf '%s\n' "$SST_PW" > /root/.sst_pw
printf '%s\n' "$APP_PW" > /root/.app_pw
chmod 600 /root/.sst_pw /root/.app_pw
echo "users created"

